INSERT INTO interview_experiences_pgvector (experience_id, company_name, role, batch, branch, author, date, title, technical_topics, key_questions, preparation_tips, full_text, embedding) VALUES ('886432ed39a81dd69079a0f025425c7089b0bb8c53583488806e771226094af0', 'Clear', '', '2022-2026', '', 'RICHA VASUDEVA', '14 Oct 2026', 'Clear Interview Experience', '{"Operating Systems"}', '{}', '', 'The interview process was very smooth and ctp was helpful in that .

