INSERT INTO interview_experiences_pgvector (experience_id, company_name, role, batch, branch, author, date, title, technical_topics, key_questions, preparation_tips, full_text, embedding) VALUES ('73a3de06916210c8b7b5b36bc22bf8665dd5dda7a09de5382dcc8188a0347501', 'Infosys', '', '2022-2026', '', 'HAPPY KUMAR', '18 Sept 2026', 'Infosys Interview Experience – 2 Coding Rounds + Technical Interview', '{"DSA"}', '{}', '', 'The coding rounds were quite tough and required good problem-solving and coding skills. After clearing them, the technical interview was comparatively easy.

